    }
    selectAll.checked = checked.length > 0 && checked.length === rowCheckboxes.length;
    selectAll.indeterminate = checked.length > 0 && checked.length < rowCheckboxes.length;
    formRunnerIds.value = checked.map((c) => c.getAttribute('data-runner-id')!).join(',');
  };

The hidden `ids` input is populated only once at init, when nothing is selected, so it is always empty. The bulk form therefore submits no IDs and the action does nothing. Update the input inside `refresh()` on every selection change.

Improved code:
const collectSelectedIds = () => {
  const ids: string[] = [];
  for (const cb of rowCheckboxes) {
    if (cb.checked) ids.push(cb.getAttribute('data-runner-id')!);
  }
  return ids.join(',');
};
const syncIds = () => {
  formRunnerIds.value = collectSelectedIds();
};
selectAll.addEventListener('change', syncIds);
for (const cb of rowCheckboxes) cb.addEventListener('change', syncIds);
syncIds();
refresh();

